import json

def count_by_tag(notes):
    tag_counts = {}
    for note in notes:
        tags = note.get('tags', [])
        for tag in tags:
            if tag in tag_counts:
                tag_counts[tag] += 1
            else:
                tag_counts[tag] = 1
    return tag_counts

# Example usage:
if __name__ == '__main__':
    notes = json.loads('WEB_PAYLOAD_98765432')
    print(count_by_tag(notes))

